function boxBlur(data,w,h,radius){
  var r=Math.max(0,Math.round(radius));
  if(r===0) return data;
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var sr=0,sg=0,sb=0,sa=0,n=0;
    for(var yy=Math.max(0,y-r);yy<=Math.min(h-1,y+r);yy++) for(var xx=Math.max(0,x-r);xx<=Math.min(w-1,x+r);xx++){
      var i=(yy*w+xx)*4; sr+=data[i]; sg+=data[i+1]; sb+=data[i+2]; sa+=data[i+3]; n++;
    }
    var p=(y*w+x)*4; out[p]=sr/n; out[p+1]=sg/n; out[p+2]=sb/n; out[p+3]=sa/n;
  }
  return out;
}
function wcHash(x,y){ var n=((x*374761393+y*668265263)>>>0); n=((n^(n>>>13))*1274126177)>>>0; n=n^(n>>>16); return (n>>>0)/4294967296; }

function stampProcess(data,w,h,opts){
