  if(thr<0)thr=0; else if(thr>255)thr=255;
  if(distress<0)distress=0; else if(distress>0.9)distress=0.9;
  if(r_<0)r_=0; else if(r_>255)r_=255; if(g_<0)g_=0; else if(g_>255)g_=255; if(b_<0)b_=0; else if(b_>255)b_=255;
  var out=new Uint8ClampedArray(data.length);
  for(var y=0;y<h;y++) for(var x=0;x<w;x++){
    var p=(y*w+x)*4;
    var L=0.299*data[p]+0.587*data[p+1]+0.114*data[p+2];
    var ink=L<thr?(1-L/thr):0;
    var nz=wcHash(x,y);
    ink=ink*(1-distress*(1-nz));
    if(ink<0)ink=0; else if(ink>1)ink=1;
    var pr=244+(wcHash(x+7,y+3)-0.5)*10, pg=242+(wcHash(x+3,y+9)-0.5)*10, pb=234+(wcHash(x+11,y+5)-0.5)*10;
